class CircuitBreaker:
    def __init__(self, threshold=2):
        self.threshold = threshold
        self.failures = 0
        self.state = 'CLOSED'

    def call(self, func):
        if self.state == 'OPEN':
            raise RuntimeError('Circuit is OPEN')
        try:
            res = func()
            self.failures = 0
            return res
        except Exception:
            raise

